import type { ButtonHTMLAttributes, RefObject } from 'react';

import { usePress } from './usePress.js';
import { mergeProps } from '../../../core/utils/merge-props.js';
import type { ButtonAria, AriaButtonProps } from '../types/button-aria.js';

/**
 * Provides the behavior and accessibility implementation for a button component. Handles mouse, keyboard, and touch interactions,
 * focus behavior, and ARIA props for both native button elements and custom element types.
 * @param props - Props to be applied to the button.
 * @param ref - A ref to a DOM element for the button.
 * @internal
 */
export function _useButton(
  props: AriaButtonProps,
  ref: RefObject<Element>,
): ButtonAria<ButtonHTMLAttributes<HTMLButtonElement>> {
  const { isDisabled, onPress, type = 'button' } = props;
  const additionalProps = {
    type,
    disabled: isDisabled,
  };

  const { pressProps, isPressed } = usePress({
    onPress,
    isDisabled,
    ref,
  });

  return {
    isPressed, // Used to indicate press state for visual
    buttonProps: mergeProps(additionalProps, pressProps, {
      'aria-haspopup': props['aria-haspopup'],
      'aria-expanded': props['aria-expanded'],
      'aria-controls': props['aria-controls'],
      'aria-pressed': props['aria-pressed'],
    }),
  };
}
